db:note.db:programlisting:
// Connect using qOverload:
connect(testClass, qOverload<const QString &>(&TestClass::dataChanged),
        receiver, &ReceiverClass::slot);

// Or using a lambda:
connect(testClass, qOverload<const QString &>(&TestClass::dataChanged),
        this, [](const QString &value) { /* handle dataChanged */ });

// Connect using qOverload:
connect(testClass, qOverload<int>(&TestClass::dataChanged),
        receiver, &ReceiverClass::slot);

// Or using a lambda:
connect(testClass, qOverload<int>(&TestClass::dataChanged),
        this, [](int value) { /* handle dataChanged */ });

// Connect using qOverload:
connect(sender, &SenderClass::signal,
        testClass, qOverload<const QString &>(&TestClass::process));

// Or using a lambda as wrapper:
connect(sender, &SenderClass::signal,
        testClass, [receiver = testClass](const QString &value) { receiver->process(value); });

// Connect using qOverload:
connect(sender, &SenderClass::signal,
        testClass, qOverload<int>(&TestClass::process));

// Or using a lambda as wrapper:
connect(sender, &SenderClass::signal,
        testClass, [receiver = testClass](int value) { receiver->process(value); });
